{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C48"],
      "claim": "In ten healthy male volunteers, ipratropium bromide had an absolute oral bioavailability of 3.3% (range 0.9-6.1%) after a 20 mg oral dose, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "In six healthy male volunteers, physostigmine had a mean absolute bioavailability of 3% after oral solution administration, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "In humans, a 20 mg racemic nitrendipine tablet had an absolute bioavailability of 10.7 ± 4.7% (range 5.2-19.9%), below the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most condition-matched absolute oral bioavailability measurements in humans are below 20% (e.g., 3.3%, 3%, 10.7%), supporting a low prediction; outlier high values and dose-dependent/mixed ranges lower confidence.",
  "evidence_gaps": [
    "Some records within otherwise low-bioavailability molecules report values above 20% (e.g., C41, C47, C21, C26, C33), but they are outliers or less condition-matched.",
    "One evidence molecule provides only a wide range (5-40%) spanning the threshold, and another shows dose-dependent values (10% at 100 µg vs 22-22.7% at 300 µg), so those records are not decisive."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

